import os, json
import numpy as np
try:
    from scipy.optimize import minimize
except Exception:
    minimize = None

N = 26
R_MIN = 1e-6
SAFETY = 1e-9
TOL_EQ = 1e-8

P_C = 'storage/noesis/latest_centers.txt'
P_R = 'storage/noesis/latest_radii.txt'
LOG = 'storage/noesis/exports/sbrg_v1_log.json'

# ----------------- Utilities -----------------
def load_snapshot():
    c = np.loadtxt(P_C, dtype=float).reshape(N,2)
    r = np.loadtxt(P_R, dtype=float).reshape(N,)
    return np.array(c,float), np.array(r,float)

def boundary_caps(c, eps=SAFETY):
    x = c[:,0]; y = c[:,1]
    return np.maximum(np.minimum.reduce([x, 1.0-x, y, 1.0-y]) - eps, R_MIN)

def make_feasible(c, r, eps=SAFETY, max_iter=4000):
    c = np.clip(c, 0.0, 1.0)
    r = np.minimum(r, boundary_caps(c, eps=eps))
    r = np.maximum(r, R_MIN)
    for _ in range(max_iter):
        diff = c[:,None,:] - c[None,:,:]
        dist = np.sqrt(np.sum(diff**2, axis=2)) + 1e-15
        iu = np.triu_indices(N,1)
        m = dist[iu] - (r[iu[0]] + r[iu[1]])
        if np.all(m >= eps): break
        k = int(np.argmin(m))
        i, j = int(iu[0][k]), int(iu[1][k])
        need = (r[i] + r[j] - dist[i,j]) + eps
        di = min(need*0.5, r[i]-R_MIN); dj = min(need-di, r[j]-R_MIN)
        if di <= 0 and dj <= 0: r = np.maximum(r*0.999, R_MIN)
        else: r[i] -= di; r[j] -= dj
        r = np.minimum(r, boundary_caps(c, eps=eps))
    return c, np.maximum(r - SAFETY, R_MIN)

def slacks(c, r):
    x = c[:,0]; y = c[:,1]
    s_xL = x - r
    s_xR = 1.0 - x - r
    s_yB = y - r
    s_yT = 1.0 - y - r
    diff = c[:,None,:] - c[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    s_pairs = dist - (r[:,None] + r[None,:])
    return (s_xL, s_xR, s_yB, s_yT), s_pairs

def active_sets(c, r, tol=TOL_EQ):
    (s_xL, s_xR, s_yB, s_yT), s_pairs = slacks(c, r)
    b = []
    for i in range(N):
        if s_xL[i] <= tol: b.append((i,'xL'))
        if s_xR[i] <= tol: b.append((i,'xR'))
        if s_yB[i] <= tol: b.append((i,'yB'))
        if s_yT[i] <= tol: b.append((i,'yT'))
    p = []
    for i in range(N):
        for j in range(i+1, N):
            if s_pairs[i,j] <= tol: p.append((i,j))
    return b, p

def degree_from_pairs(pairs):
    deg = np.zeros(N, dtype=int)
    for (i,j) in pairs: deg[i]+=1; deg[j]+=1
    return deg

# ----------------- SLSQP model -----------------
def pack_to_z(c, r):
    Z = np.zeros((N,3), dtype=float)
    Z[:,:2] = c; Z[:,2] = r
    return Z.ravel()

def z_to_pack(z):
    Z = np.array(z, dtype=float).reshape(N,3)
    return Z[:,:2], Z[:,2]

def objective(z):
    return -np.sum(z[2::3])

def objective_jac(z):
    g = np.zeros_like(z); g[2::3] = -1.0; return g

def ineq_boundary(z):
    Z = np.array(z, dtype=float).reshape(N,3)
    x, y, r = Z[:,0], Z[:,1], Z[:,2]
    return np.concatenate([x - r, 1.0 - x - r, y - r, 1.0 - y - r])

def jac_boundary(z):
    J = np.zeros((4*N, 3*N), dtype=float)
    for i in range(N):
        xi = 3*i; yi = xi+1; ri = xi+2
        J[i, xi] = 1.0;        J[i, ri] = -1.0
        J[N+i, xi] = -1.0;     J[N+i, ri] = -1.0
        J[2*N+i, yi] = 1.0;    J[2*N+i, ri] = -1.0
        J[3*N+i, yi] = -1.0;   J[3*N+i, ri] = -1.0
    return J

def ineq_nonoverlap(z):
    Z = np.array(z, dtype=float).reshape(N,3)
    C = Z[:,:2]; r = Z[:,2]
    diff = C[:,None,:] - C[None,:,:]
    dist = np.sqrt(np.sum(diff**2, axis=2))
    iu = np.triu_indices(N,1)
    return dist[iu] - (r[iu[0]] + r[iu[1]])

def jac_nonoverlap(z):
    Z = np.array(z, dtype=float).reshape(N,3)
    C = Z[:,:2]
    m = N*(N-1)//2
    J = np.zeros((m, 3*N), dtype=float)
    idx = 0
    for i in range(N):
        xi = 3*i; yi = xi+1; ri = xi+2
        for j in range(i+1,N):
            xj = 3*j; yj = xj+1; rj = xj+2
            dx = C[i,0]-C[j,0]; dy = C[i,1]-C[j,1]
            d = np.hypot(dx,dy)
            if d < 1e-12:
                gx_i=gy_i=gx_j=gy_j=0.0
            else:
                invd = 1.0/d
                gx_i = dx*invd; gy_i = dy*invd
                gx_j = -gx_i;   gy_j = -gy_i
            J[idx, xi] = gx_i;  J[idx, yi] = gy_i;  J[idx, ri] = -1.0
            J[idx, xj] = gx_j;  J[idx, yj] = gy_j;  J[idx, rj] = -1.0
            idx += 1
    return J

# Equality row for a given boundary label
def eq_row_for(i, kind):
    row = np.zeros(3*N, dtype=float)
    xi = 3*i; yi = xi+1; ri = xi+2
    if kind in ('xL','xmin'):
        row[xi]=1.0;  row[ri]=-1.0;  off=0.0
    elif kind in ('xR','xmax'):
        row[xi]=-1.0; row[ri]=-1.0;  off=1.0
    elif kind in ('yB','ymin'):
        row[yi]=1.0;  row[ri]=-1.0;  off=0.0
    elif kind in ('yT','ymax'):
        row[yi]=-1.0; row[ri]=-1.0;  off=1.0
    else:
        off=0.0
    return row, off

# ----------------- Main attempt -----------------
def construct_packing():
    c0, r0 = load_snapshot()
    c0, r0 = make_feasible(c0, r0)
    base_sum = float(np.sum(r0))

    # Identify boundary equalities and interior degrees
    b_act, p_act = active_sets(c0, r0, tol=TOL_EQ)
    deg = degree_from_pairs(p_act)

    if not b_act or minimize is None:
        # Fallback: return baseline
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)

    # Choose one boundary equality to relax: boundary contact on disc with maximal interior degree
    # If multiple, pick the first by list order.
    best = None; best_deg = -1
    for (i, kind) in b_act:
        if deg[i] > best_deg:
            best_deg = deg[i]; best = (int(i), str(kind))
    i_relax, kind_relax = best

    # Build equality constraints for all boundary actives except the chosen one
    eq_rows = []
    for (i, kind) in b_act:
        i = int(i); kind = str(kind)
        if i==i_relax and kind==kind_relax: continue
        row, off = eq_row_for(i, kind)
        # eq: row·z + (off) == 0  (off is +1 for xR/yT forms)
        eq_rows.append((row, off))

    z0 = pack_to_z(c0, r0)

    # Trust region box around baseline (small componentwise bounds)
    step_c = 8e-4; step_r = 8e-4
    A_tr = []; b_tr = []
    for j in range(3*N):
        e = np.zeros(3*N, dtype=float); e[j]=1.0
        lim = step_r if (j%3)==2 else step_c
        A_tr.append( e.copy()); b_tr.append(z0[j] + lim)
        A_tr.append(-e.copy()); b_tr.append(-(z0[j] - lim))
    A_tr = np.vstack(A_tr); b_tr = np.array(b_tr, dtype=float)

    # Assemble constraints
    cons = [
        {'type':'ineq','fun': ineq_boundary,   'jac': jac_boundary},
        {'type':'ineq','fun': ineq_nonoverlap, 'jac': jac_nonoverlap},
        {'type':'ineq','fun': (lambda z, A=A_tr, b=b_tr: b - A.dot(z)),
         'jac' : (lambda z, A=A_tr: -A)}
    ]
    for (row, off) in eq_rows:
        cons.append({'type':'eq',
                     'fun': (lambda z, r=row, of=off: float(np.dot(r, z) + of)),
                     'jac': (lambda z, r=row: r)})

    bounds = []
    for _ in range(N):
        bounds.extend([(0.0,1.0), (0.0,1.0), (R_MIN, 0.5)])

    # Seed: tiny inward nudge of the relaxed disc along its wall normal
    c_seed, r_seed = c0.copy(), r0.copy()
    eps = 5e-4
    if kind_relax in ('xL','xmin'):
        c_seed[i_relax,0] = min(1.0, c_seed[i_relax,0] + eps)
    elif kind_relax in ('xR','xmax'):
        c_seed[i_relax,0] = max(0.0, c_seed[i_relax,0] - eps)
    elif kind_relax in ('yB','ymin'):
        c_seed[i_relax,1] = min(1.0, c_seed[i_relax,1] + eps)
    elif kind_relax in ('yT','ymax'):
        c_seed[i_relax,1] = max(0.0, c_seed[i_relax,1] - eps)
    c_seed, r_seed = make_feasible(c_seed, r_seed)

    try:
        res = minimize(objective, pack_to_z(c_seed, r_seed), method='SLSQP', jac=objective_jac,
                       bounds=bounds, constraints=cons,
                       options={'maxiter': 800, 'ftol': 1e-9, 'disp': False})
    except Exception:
        res = None

    if res is not None and res.success:
        c_opt, r_opt = z_to_pack(res.x)
        c_opt, r_opt = make_feasible(c_opt, r_opt)
        cand_sum = float(np.sum(r_opt))
    else:
        c_opt, r_opt = c0, r0
        cand_sum = base_sum

    # Log diagnostics
    out = {
        'relaxed_boundary': {'i': int(i_relax), 'kind': kind_relax},
        'baseline_sum': base_sum,
        'candidate_sum': cand_sum,
        'degree_relaxed_disc': int(best_deg),
        'n_boundary_eq_enforced': int(len(eq_rows)),
        'trust_region': {'step_c': step_c, 'step_r': step_r},
        'success': bool(res is not None and res.success)
    }
    try:
        os.makedirs(os.path.dirname(LOG), exist_ok=True)
        with open(LOG, 'w') as f: json.dump(out, f, indent=2)
    except Exception:
        pass

    if cand_sum > base_sum + 1e-12:
        return c_opt.astype(float), np.maximum(r_opt - SAFETY, R_MIN).astype(float)
    else:
        return c0.astype(float), np.maximum(r0 - SAFETY, R_MIN).astype(float)
